import{_ as t,o as e,c as a,ae as o}from"./chunks/framework.Dzr56EFm.js";const c=JSON.parse('{"title":"设计趋势 - 2026-08-10","description":"","frontmatter":{"date":"2026-08-10T00:00:00.000Z","category":"UX Trend"},"headers":[],"relativePath":"daily/2026-08-10-uxtrend.md","filePath":"daily/2026-08-10-uxtrend.md"}'),n={name:"daily/2026-08-10-uxtrend.md"};function s(i,r,g,p,h,l){return e(),a("div",null,[...r[0]||(r[0]=[o('<h1 id="设计趋势-2026-08-10" tabindex="-1">设计趋势 - 2026-08-10 <a class="header-anchor" href="#设计趋势-2026-08-10" aria-label="Permalink to &quot;设计趋势 - 2026-08-10&quot;">​</a></h1><blockquote><p>AI交互方式、Prompt UX、Agent UX、Workflow</p></blockquote><h2 id="今日概览" tabindex="-1">今日概览 <a class="header-anchor" href="#今日概览" aria-label="Permalink to &quot;今日概览&quot;">​</a></h2><p>今日设计趋势聚焦于人工智能与用户体验的融合。关键动态包括面向代理的用户体验设计原则，以及AI工作流设计中的常见误区。最值得关注的是，AI不应被视作“人”，而是作为工具来设计工作流程，以及Figma社区提供的AI工作流，助力创意内容生成。</p><hr><h3 id="_1-面向代理的用户体验设计" tabindex="-1">1. 面向代理的用户体验设计 <a class="header-anchor" href="#_1-面向代理的用户体验设计" aria-label="Permalink to &quot;1. 面向代理的用户体验设计&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/microsoft-design/ux-design-for-agents-11336728b445" target="_blank" rel="noreferrer">UX design for agents</a></p><p><strong>一句话摘要</strong>: 设计原则推动数字设备中新型用户体验的发展。</p><p><strong>能解决什么问题</strong>: 传统UX原则无法完全应对AI驱动代理系统的独特挑战。</p><p><strong>产品应用</strong>: 适用于产品开发，以人为中心，加速开发并强调AI中的人本价值。</p><p><strong>示例场景</strong>: AI代理系统辅助团队协作，提升工作效率。</p><hr><h3 id="_2-人工智能工作流设计的误区" tabindex="-1">2. 人工智能工作流设计的误区 <a class="header-anchor" href="#_2-人工智能工作流设计的误区" aria-label="Permalink to &quot;2. 人工智能工作流设计的误区&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://skooloflife.medium.com/the-biggest-mistake-in-ai-workflow-design-mimicking-human-process-instead-of-optimizing-function-628bfa37aa02" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: AI系统失败常因设计误区：将AI视作“人”而非工具。</p><p><strong>能解决什么问题</strong>: 解决将AI错误人格化导致的设计问题。</p><p><strong>产品应用</strong>: 适用于产品设计，通过直接嵌入功能而非模拟人的角色。</p><p><strong>示例场景</strong>: 在客户服务中直接调用AI功能处理查询。</p><hr><h3 id="_3-人工智能时代下的用户体验2-0-代理体验设计" tabindex="-1">3. 人工智能时代下的用户体验2.0：代理体验设计 <a class="header-anchor" href="#_3-人工智能时代下的用户体验2-0-代理体验设计" aria-label="Permalink to &quot;3. 人工智能时代下的用户体验2.0：代理体验设计&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@purvashobhit/ux-2-0-agent-experience-experience-design-in-the-age-of-ai-agents-a32230569449" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: 在人工智能代理时代，用户体验设计需扩展至人机逻辑、沟通和信任。</p><p><strong>能解决什么问题</strong>: 解决非人类用户（如AI代理）的体验设计问题，提升人机协作效率。</p><p><strong>产品应用</strong>: 适用于需要AI代理与人类协作的产品，如自动化客服、智能助手等。</p><p><strong>示例场景</strong>: AI代理自动预约医生，提高预约流程效率。</p><hr><h3 id="_4-设计ai辅助工作流程" tabindex="-1">4. 设计AI辅助工作流程 <a class="header-anchor" href="#_4-设计ai辅助工作流程" aria-label="Permalink to &quot;4. 设计AI辅助工作流程&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@krithika_bala/designing-ai-assisted-workflows-871facbc694f" target="_blank" rel="noreferrer">Designing AI-Assisted Workflows</a></p><p><strong>一句话摘要</strong>: 构建信任的三个设计原则：展示AI推理、允许用户覆盖决策、强调AI支持而非替代。</p><p><strong>能解决什么问题</strong>: 如何设计AI辅助系统以提高工作效率和用户信任。</p><p><strong>产品应用</strong>: 可以应用到需要智能决策支持的实际产品中，如文档处理、信息提取等。</p><p><strong>示例场景</strong>: 企业文档处理流程中，AI辅助识别、提取信息、建议下一步操作。</p><hr><h3 id="_5-figma中的ai工作流-图像、视频与创意生成" tabindex="-1">5. Figma中的AI工作流：图像、视频与创意生成 <a class="header-anchor" href="#_5-figma中的ai工作流-图像、视频与创意生成" aria-label="Permalink to &quot;5. Figma中的AI工作流：图像、视频与创意生成&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.figma.com/community/ai-workflows" target="_blank" rel="noreferrer">AI Workflows for Image, Video &amp; Creative Generation | Figma</a></p><p><strong>一句话摘要</strong>: Figma社区提供的AI工作流，帮助用户结构化生成图像、视频等创意内容。</p><p><strong>能解决什么问题</strong>: 解决AI创意内容生成过程中模型选择、参考和创意步骤的困难。</p><p><strong>产品应用</strong>: 适用于实际产品中，通过自定义工作流输入，探索创意方向，生成产品图像。</p><p><strong>示例场景</strong>: 为营销活动创建内容，使用工作流生成产品视觉图像。</p><hr><h3 id="_6-设计师眼中的2026-ai提升设计质量" tabindex="-1">6. 设计师眼中的2026：AI提升设计质量 <a class="header-anchor" href="#_6-设计师眼中的2026-ai提升设计质量" aria-label="Permalink to &quot;6. 设计师眼中的2026：AI提升设计质量&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/design-bootcamp/product-designers-are-not-being-replaced-they-are-being-sorted-6e2fb0492ed2" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: AI在设计领域提升质量与速度，设计师转向策略与情感判断。</p><p><strong>能解决什么问题</strong>: AI辅助设计提高了效率，但需人类完成精细调整和创意决策。</p><p><strong>产品应用</strong>: 适用于产品设计，设计师利用AI进行初步设计，再进行人工优化。</p><p><strong>示例场景</strong>: 设计师使用AI生成原型，然后进行细节调整和用户测试。</p><hr><h3 id="_7-使用cursor-ai快速构建react网页应用" tabindex="-1">7. 使用Cursor AI快速构建React网页应用 <a class="header-anchor" href="#_7-使用cursor-ai快速构建react网页应用" aria-label="Permalink to &quot;7. 使用Cursor AI快速构建React网页应用&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/ux-planet/vibe-coding-for-web-with-cursor-ai-0059aa5e5803" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: Cursor AI辅助快速可视化构建网页应用，但需迭代完善。</p><p><strong>能解决什么问题</strong>: 解决非专业人士快速构建网页应用的难题。</p><p><strong>产品应用</strong>: 适用于初步设计阶段，需结合专业反馈进行迭代。</p><p><strong>示例场景</strong>: 设计师利用Cursor AI快速搭建原型，收集反馈。</p><hr><h3 id="_8-ai代理工作流设计模式概览" tabindex="-1">8. AI代理工作流设计模式概览 <a class="header-anchor" href="#_8-ai代理工作流设计模式概览" aria-label="Permalink to &quot;8. AI代理工作流设计模式概览&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/binome/ai-agent-workflow-design-patterns-an-overview-cf9e1f609696" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: 探讨AI代理工作流设计模式，分类并举例说明。</p><p><strong>能解决什么问题</strong>: 如何设计AI代理以模拟人类推理，提高任务执行效率。</p><p><strong>产品应用</strong>: 可应用于实际产品，作为任务协调器处理不同问题。</p><p><strong>示例场景</strong>: 基于这些原则开发AI代理，处理复杂任务。</p><hr><h3 id="_9-ai用户体验模式介绍" tabindex="-1">9. AI用户体验模式介绍 <a class="header-anchor" href="#_9-ai用户体验模式介绍" aria-label="Permalink to &quot;9. AI用户体验模式介绍&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://lukelance.medium.com/ai-ux-design-patterns-53d9e378f808" target="_blank" rel="noreferrer">Medium</a></p><p><strong>一句话摘要</strong>: AI用户体验模式旨在指导设计有效的AI交互体验。</p><p><strong>能解决什么问题</strong>: 解决传统UI设计无法适应AI交互需求的问题。</p><p><strong>产品应用</strong>: 适用于任何涉及AI的产品设计，通过评估和选择适合的模式。</p><p><strong>示例场景</strong>: 智能助手通过自然语言理解用户意图并提供服务。</p><hr><h3 id="_10-代理式用户体验-设计代理系统的7原则" tabindex="-1">10. 代理式用户体验：设计代理系统的7原则 <a class="header-anchor" href="#_10-代理式用户体验-设计代理系统的7原则" aria-label="Permalink to &quot;10. 代理式用户体验：设计代理系统的7原则&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/design-bootcamp/agentic-ux-7-principles-for-designing-systems-with-agents-019512c2caa9" target="_blank" rel="noreferrer">Agentic UX: 7 principles for designing systems with agents</a></p><p><strong>一句话摘要</strong>: 设计代理系统时应考虑上下文双向流动，确保行为可信赖。</p><p><strong>能解决什么问题</strong>: 解决代理系统与用户交互时的上下文断连和信任问题。</p><p><strong>产品应用</strong>: 适用于需要智能代理辅助的任何产品，如客服、任务自动化等。</p><p><strong>示例场景</strong>: 智能助手在用户工作流中自动处理任务，无需切换界面。</p><hr>',75)])])}const m=t(n,[["render",s]]);export{c as __pageData,m as default};
